-- DRAFT: requires an ORDS-enabled development schema.
-- Keep NOT_PUBLISHED until authentication, authorization and tests are complete.
BEGIN
  ORDS.DEFINE_MODULE(p_module_name => 'migration.migration_service',
    p_base_path => '/migration/migration_service/',
    p_status => 'NOT_PUBLISHED', p_items_per_page => 25);
  ORDS.DEFINE_TEMPLATE(p_module_name => 'migration.migration_service', p_pattern => 'validate');
  ORDS.DEFINE_HANDLER(p_module_name => 'migration.migration_service', p_pattern => 'validate',
    p_method => 'POST', p_source_type => ORDS.source_type_plsql,
    p_mimes_allowed => 'application/json',
    p_source => 'DECLARE
      l_payload CLOB := :body_text;
      l_result CLOB;
    BEGIN
      l_result := MIGRATION_SERVICE.validate_payload(l_payload);
      -- TODO: implement bounded/chunked JSON response output and error mapping.
      :status_code := 501;
    END;');
END;
/
